```java
// SRP: clase que solo envía notificaciones
interface Notifier {
    void send(String message);
}

// OCP y DIP: podemos añadir nuevos notifiers sin tocar el código cliente
class EmailNotifier implements Notifier {
    public void send(String message) {
        System.out.println("Email: " + message);
    }
}

class SmsNotifier implements Notifier {
    public void send(String message) {
        System.out.println("SMS: " + message);
    }
}

// Cliente que depende de la abstracción (DIP)
class AlertService {
    private final Notifier notifier;
    public AlertService(Notifier notifier) {
        this.notifier = notifier;
    }
    public void alert(String msg) {
        notifier.send(msg);
    }
}

// Uso
AlertService service = new AlertService(new EmailNotifier());
service.alert("¡Sistema operativo!");
